from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

RENEWAL_STATUSES = ("active", "lapsed", "suspended")
PAYMENT_METHODS = ("card", "transfer")


def _validate_tier(member: dict) -> str | None:
    if member["tier"] not in TIER_FEES:
        return "unknown tier"
    return None


def _validate_status_fields(status: str, member: dict) -> str | None:
    """Validate the member fields a non-active status requires."""
    if status == "lapsed":
        if not isinstance(member.get("expired_days"), int) or member["expired_days"] < 0:
            return "bad expiry"
    elif status == "suspended":
        if not isinstance(member.get("strikes"), int) or member["strikes"] < 0:
            return "bad strikes"
        if member["strikes"] >= MAX_STRIKES:
            return "too many strikes"
    return None


def _validate_amount(payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    return None


def _validate_method(payment: dict) -> str | None:
    if payment["method"] not in PAYMENT_METHODS:
        return "unsupported method"
    return None


def _fee_and_status(status: str, member: dict) -> tuple[int, str]:
    """Resolve the fee and resulting status for an eligible member."""
