from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

RENEWAL_STATUSES = ("active", "lapsed", "suspended")
PAYMENT_METHODS = ("card", "transfer")


def _validate_tier(member: dict) -> str | None:
    if member["tier"] not in TIER_FEES:
        return "unknown tier"
    return None


def _validate_status_fields(status: str, member: dict) -> str | None:
    """Validate the member fields a non-active status requires."""
    if status == "lapsed":
        if not isinstance(member.get("expired_days"), int) or member["expired_days"] < 0:
            return "bad expiry"
    elif status == "suspended":
        if not isinstance(member.get("strikes"), int) or member["strikes"] < 0:
            return "bad strikes"
        if member["strikes"] >= MAX_STRIKES:
            return "too many strikes"
    return None


def _validate_amount(payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    return None


def _validate_method(payment: dict) -> str | None:
    if payment["method"] not in PAYMENT_METHODS:
        return "unsupported method"
    return None


def _fee_and_status(status: str, member: dict) -> tuple[int, str]:
    """Resolve the fee and resulting status for an eligible member."""
    base = TIER_FEES[member["tier"]]
    if status == "active":
        return base, "renewed"
    if status == "lapsed":
        if member["expired_days"] <= GRACE_DAYS:
            return base + LATE_FEE, "renewed"
        return base + REINSTATE_SURCHARGE, "reinstated"
    return base + base // 2, "reactivated"


def _make_receipt(method: str, member_id: str, new_status: str, fee: int) -> str:
    return method + ":" + member_id + ":" + new_status + ":" + str(fee)


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}
    if status not in RENEWAL_STATUSES:
        return {"ok": False, "error": "unknown status"}

    # Validation order mirrors the original branches: tier, status-specific
    # fields, amount, method.
    for check in (_validate_tier(member),
                  _validate_status_fields(status, member),
                  _validate_amount(payment),
                  _validate_method(payment)):
        if check is not None:
            return {"ok": False, "error": check}

    fee, new_status = _fee_and_status(status, member)
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    receipt = _make_receipt(payment["method"], member["id"], new_status, fee)
    return {"ok": True, "status": new_status, "fee": fee, "receipt": receipt}

